#include <cassert>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
enum class Action { Wait, Approach, Retreat, Attack };
struct Seen { bool visible; int distance; int health; int energy; };
// 관찰된 값만 사용하는 독창적 CPU 정책. 숨은 상대 입력은 받지 않는다.
Action decide(const Seen& s, int reactionTicks, int cooldownTicks) {
    if(s.distance<0||s.distance>100||s.health<0||s.health>100||
       s.energy<0||s.energy>10||reactionTicks<0||cooldownTicks<0)
        throw std::invalid_argument("invalid observation");
    if(reactionTicks>0||!s.visible||s.health==0)return Action::Wait;
    if(s.health<20 && s.distance<5)return Action::Retreat;
    if(s.distance>3)return Action::Approach;
    if(cooldownTicks==0 && s.energy>=2)return Action::Attack;
    return Action::Wait;
}
int main(){
    assert(decide({true,3,100,2},0,0)==Action::Attack);
    assert(decide({true,4,100,2},0,0)==Action::Approach);
    assert(decide({true,3,19,2},0,0)==Action::Retreat);
    assert(decide({true,3,20,2},0,0)==Action::Attack);
    assert(decide({false,3,100,2},0,0)==Action::Wait);
    assert(decide({true,3,100,2},1,0)==Action::Wait);
    assert(decide({true,3,100,2},0,1)==Action::Wait);
    assert(decide({true,3,100,1},0,0)==Action::Wait);
    for(int d=0;d<=100;++d)for(int h=0;h<=100;++h){
        const Action a=decide({true,d,h,2},0,0);
        if(a==Action::Attack)assert(d<=3&&h>=20);
        if(h==0)assert(a==Action::Wait);
    }
    bool rejected=false;try{decide({true,-1,50,2},0,0);}catch(const std::invalid_argument&){rejected=true;}
    assert(rejected);std::cout<<"CPU policy tests passed\n";
}
